ALTER TABLE "conversation_ai_response_jobs" ADD COLUMN "agent_decision" varchar(16);--> statement-breakpoint
ALTER TABLE "conversation_ai_response_jobs" ADD COLUMN "escalation_reason" varchar(64);--> statement-breakpoint
UPDATE "conversation_ai_response_jobs" SET "agent_decision" = 'RESPOND' WHERE "status" = 'SUCCEEDED';--> statement-breakpoint
ALTER TABLE "conversation_ai_response_jobs" ADD CONSTRAINT "conversation_ai_response_jobs_decision_check" CHECK (("conversation_ai_response_jobs"."status" = 'SUCCEEDED' and "conversation_ai_response_jobs"."agent_decision" is not null and "conversation_ai_response_jobs"."agent_decision" in ('RESPOND','ESCALATE')) or ("conversation_ai_response_jobs"."status" <> 'SUCCEEDED' and "conversation_ai_response_jobs"."agent_decision" is null));--> statement-breakpoint
ALTER TABLE "conversation_ai_response_jobs" ADD CONSTRAINT "conversation_ai_response_jobs_escalation_check" CHECK (("conversation_ai_response_jobs"."agent_decision" is not distinct from 'ESCALATE' and "conversation_ai_response_jobs"."escalation_reason" is not null and "conversation_ai_response_jobs"."escalation_reason" in ('PRICE_QUOTATION','DISCOUNT_REQUEST','PAYMENT_TERMS','CREDIT_REQUEST','CONTRACT_COMMITMENT','LEGAL_OR_REGULATORY_GUARANTEE','CUSTOMS_GUARANTEE','DELIVERY_COMMITMENT','AVAILABILITY_UNVERIFIED','PRODUCT_FACT_UNAVAILABLE','CONTRADICTORY_TRUSTED_DATA','UNSUPPORTED_REQUEST','LOW_CONFIDENCE','INVALID_TOOL_CALL','UNKNOWN_TOOL','LOOP_LIMIT_REACHED','EXECUTION_DEADLINE_REACHED')) or ("conversation_ai_response_jobs"."agent_decision" is distinct from 'ESCALATE' and "conversation_ai_response_jobs"."escalation_reason" is null));
